mkdir -p tools
cat > tools/make_flat_repo_jsonl.py <<'PY'
#!/usr/bin/env python3
import json, pathlib, hashlib, subprocess

root = pathlib.Path('.').resolve()
out = root / 'snapsurf_repo.flat.jsonl'
include_ext = {'.md','.txt','.asm','.inc','.snapsurf','.expected','.sh','.cmake','.rs','.c','.h','.json','.jsonl','.sfile'}
skip_dirs = {'.git','build','.cache','target','node_modules','__pycache__'}

def git_sha():
    try:
        return subprocess.check_output(['git','rev-parse','HEAD'], text=True).strip()
    except Exception:
        return None

with out.open('w', encoding='utf-8') as w:
    w.write(json.dumps({'type':'repo_meta','repo':'SnapSurf-lang','commit':git_sha()}, ensure_ascii=False) + '\n')
    for p in sorted(root.rglob('*')):
        if not p.is_file():
            continue
        rel = p.relative_to(root)
        if any(part in skip_dirs for part in rel.parts):
            continue
        if p.suffix not in include_ext and p.name not in {'CMakeLists.txt','LICENSE','SECURITY.md','README.md'}:
            continue
        try:
            data = p.read_text(encoding='utf-8')
        except UnicodeDecodeError:
            continue
        w.write(json.dumps({
            'type':'file',
            'path':str(rel),
            'bytes':len(data.encode('utf-8')),
            'sha256':hashlib.sha256(data.encode('utf-8')).hexdigest(),
            'content':data
        }, ensure_ascii=False, separators=(',', ':')) + '\n')
print(out)
PY
python3 tools/make_flat_repo_jsonl.py
